mkdir -p /app/bin /app/out; cat > /app/bin/summarize.py <<'E'
#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md."""
import sys, os, re, gzip, json
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP

KG = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45359237'),
      'oz': Decimal('0.028349523125')}
PRIORITY = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
COLS = {
    'east': ['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'],
    'lakeside': ['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'],
    'river': ['t', 'ref', 'shipped', 'weight', 'status'],
    'west': ['id', 'typ', 'shipped', 'weight', 'status', 'note'],
    'harbor': ['rec', 'ref', 'date', 'weight', 'state'],
}
DELIM = {'east': ',', 'lakeside': ',', 'river': '\t', 'west': ';', 'harbor': '|'}
BASE_DATE = {'east': 'YMD', 'lakeside': 'iso', 'river': 'MM/DD/YYYY',
             'west': 'DD.MM.YYYY', 'harbor': 'iso'}
ID_RE = re.compile(r'^\s*SH\W*0*(\d+)\s*$', re.I)
UNIT_RE = re.compile(r'^\s*([-+]?[\d.,]*\d)\s*(kg|g|lb|oz)\s*$', re.I)
FW = {
    'FW1': (42, dict(id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25), status=(25, 26)),
            'YYYYDDD', Decimal('0.001')),
    'FW2': (43, dict(type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27)),
            'YYYYMMDD', Decimal('0.01')),
    'FW3': (41, dict(id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25)),
            'YYYYDDD', Decimal('0.045359237')),
}
FW_STATUS = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned',
             'H': 'held'}


def read_text(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    m = re.search(rb'^#\s*charset\s*:\s*([\w.:-]+)', b[:4096], re.M | re.I)
    enc = m.group(1).decode('ascii') if m else 'utf-8'
    try:
        return b.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return b.decode('utf-8', 'replace') if not m else b.decode('latin-1')


def norm_status(s):
    return re.sub(r'[\s_-]+', '_', (s or '').strip().lower())


def parse_num(s, depot_style):
    s = s.strip()
    if depot_style == 'comma':      # decimal comma, dot groups
        s = s.replace('.', '').replace(',', '.')
    else:                            # dot decimal, comma groups
        s = s.replace(',', '')
    return Decimal(s)


def parse_date(s, form):
    s = s.strip()
    f = (form or '').strip()
    fl = f.lower()
    if fl == 'serial' or (re.fullmatch(r'\d{5}', s) and fl in ('serial',)):
        return date(1899, 12, 30) + timedelta(days=int(Decimal(s)))
    nums = re.split(r'\D+', s)
    nums = [n for n in nums if n]
    if len(nums) != 3:
        raise ValueError('bad date %r' % s)
    a, b, c = nums
    fu = f.upper()
    if fl in ('iso', 'ymd', 'yyyy-mm-dd') or fu.startswith('YYYY'):
        return date(int(a), int(b), int(c))
    if fl == 'dmy' or fu.startswith('DD'):
        return date(int(c), int(b), int(a))
    if fu.startswith('MM'):
        return date(int(c), int(a), int(b))
    if len(a) == 4:
        return date(int(a), int(b), int(c))
    return date(int(c), int(b), int(a))


def scan_csv(text):
    """Yield ('comment', line) or ('row', fields) from comma-delimited text with quoting."""
    i, n = 0, len(text)
    while i < n:
        if text[i] in '\r\n':
            i += 1
            continue
        if text[i] == '#':
            j = text.find('\n', i)
            j = n if j < 0 else j
            yield 'comment', text[i:j].rstrip('\r')
            i = j + 1
            continue
        fields, cur, inq = [], [], False
        while i < n:
            ch = text[i]
            if inq:
                if ch == '"':
                    if i + 1 < n and text[i + 1] == '"':
                        cur.append('"'); i += 1
                    else:
                        inq = False
                else:
                    cur.append(ch)
            elif ch == '"':
                inq = True
            elif ch == ',':
                fields.append(''.join(cur)); cur = []
            elif ch == '\n':
                break
            elif ch == '\r':
                pass
            else:
                cur.append(ch)
            i += 1
        i += 1
        fields.append(''.join(cur))
        yield 'row', fields


def scan_plain(text, delim):
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if not line.strip():
            continue
        if line.startswith('#'):
            yield 'comment', line
        else:
            yield 'row', line.split(delim)


def make_rec(typ, num, weight, ship, status):
    return dict(type=typ, num=num, weight=weight, ship=ship, status=status)


def id_num(s):
    m = ID_RE.match(s or '')
    return int(m.group(1)) if m else None


def type_of(v, depot):
    v = (v or '').strip().lower()
    if v in ('c', 'cor', 'corr', 'correction', 'amend'):
        return 'C'
    if v in ('v', 'void'):
        return 'V'
    return 'N'


def parse_delimited(depot, text):
    cols = COLS[depot]
    colset = set(cols)
    rows = scan_csv(text) if DELIM[depot] == ',' else scan_plain(text, DELIM[depot])
    seq = None
    dirs = {}
    header = None
    recs = []
    for kind, val in rows:
        if kind == 'comment':
            m = re.match(r'#\s*([^:=]+?)\s*[:=]\s*(.*?)\s*$', val)
            if m:
                name = re.sub(r'\s+', ' ', m.group(1).lower())
                v = m.group(2)
                if name == 'seq':
                    seq = int(v)
                elif name.startswith('date'):
                    dirs['date'] = v
                elif 'unit' in name:
                    dirs['unit'] = re.sub(r'\(.*?\)', '', v).strip().lower()
            else:
                m = re.match(r'#\s*\w+ export seq=(\d+)', val)
                if m:
                    seq = int(m.group(1))
            continue
        low = [f.strip().lower() for f in val]
        if all(f in colset for f in low) and len(low) > 1:
            header = low
            continue
        if header is None:
            header = cols
        # the unit in use for this row
        extra_unit = None
        row = val
        if len(row) == len(header) + 1:
            wi = header.index({'east': 'gross'}.get(depot, 'weight')) if \
                ({'east': 'gross'}.get(depot, 'weight')) in header else None
            if wi is not None and row[wi + 1].strip().lower() in KG:
                extra_unit = row[wi + 1].strip().lower()
                row = row[:wi + 1] + row[wi + 2:]
            else:
                for k, f in enumerate(row):
                    if f.strip().lower() in KG:
                        extra_unit = f.strip().lower()
                        row = row[:k] + row[k + 1:]
                        break
        d = dict(zip(header, row + [''] * (len(header) - len(row))))
        idf = d.get('id', d.get('ref', ''))
        num = id_num(idf)
        if num is None:
            continue
        typ = type_of(d.get('type', d.get('kind', d.get('t', d.get('typ', d.get('rec', ''))))), depot)
        status = d.get('status', d.get('state', ''))
        ship = None
        weight = None
        if typ != 'V':
            datekey = 'date' if depot == 'harbor' else 'shipped'
            ship = parse_date(d[datekey], dirs.get('date', BASE_DATE[depot]))
            wkey = {'east': 'gross', 'lakeside': 'gross_kg'}.get(depot, 'weight')
            ws = d.get(wkey, '')
            style = 'comma' if depot == 'west' else 'dot'
            m = UNIT_RE.match(ws)
            if wkey == 'gross_kg':
                unit = 'kg'
            else:
                unit = None
            if m:
                ws, unit = m.group(1), m.group(2).lower()
            unit = unit or extra_unit or dirs.get('unit') or 'kg'
            if unit not in KG:
                unit = 'kg'
            weight = parse_num(ws, style) * KG[unit]
        recs.append(make_rec(typ, num, weight, ship, norm_status(status)))
    return seq, recs


def parse_fixed(text):
    seq = None
    layout = None
    recs = []
    for line in text.split('\n'):
        line = line.rstrip('\r')
        if not line.strip() or '\f' in line:
            continue
        if line.startswith('#LAYOUT'):
            layout = line.split(None, 1)[1].strip().upper()
            continue
        if line.startswith('#SEQ'):
            seq = int(line.split()[1])
            continue
        if line.startswith('#'):
            continue
        if line.upper().startswith('SOUTH DEPOT'):
            continue
        name = layout
        for k, (ln, *_r) in FW.items():
            if len(line) == ln:
                name = k
        if name not in FW:
            continue
        ln, f, dform, scale = FW[name]
        if len(line) < ln:
            line = line.ljust(ln)
        g = {k: line[a:b] for k, (a, b) in f.items()}
        num = id_num(g['id'])
        if num is None:
            continue
        typ = type_of(g['type'], 'south')
        ship = weight = None
        if typ != 'V':
            s = g['shipped'].strip()
            if dform == 'YYYYDDD':
                ship = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
            else:
